/**
 * The TypeScript logic must reproduce every Python golden case
 * (worker/tests/golden/cases.json, generated by worker/tests/golden_cases.py).
 * Run: npm test
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { evaluate, fmtG } from "../lib/logic/chartfacts.ts";
import { decKey, decToString, parseDec } from "../lib/logic/decimal.ts";
import { buildPrompt, narrationData, narrationInstructions, NarrationError, normaliseApiReply, parseNarration, STORY_REQUEST, wordCount } from "../lib/logic/narrate.ts";
import { shortlist, slugify, type FindingRow } from "../lib/logic/stories.ts";
import { chartKeys, chartText, extractTokens, flattenNumbers, verifyText, type Claim } from "../lib/logic/verify.ts";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const golden: any = JSON.parse(
  readFileSync(new URL("../../worker/tests/golden/cases.json", import.meta.url), "utf8"),
);

const sameNumber = (a: string, b: string) => decKey(parseDec(a)) === decKey(parseDec(b));

test("number tokens", () => {
  for (const c of golden.tokens) {
    const got = extractTokens("f", c.text).map((t) => ({
      text: t.text,
      value: decToString(t.value),
      decimals: t.decimals,
      kind: t.kind,
      start: t.start,
      end: t.end,
    }));
    assert.deepEqual(got, c.tokens, c.text);
  }
});

test("KEYS table (flatten_numbers)", () => {
  for (const c of golden.flatten) {
    const got = flattenNumbers(c.numbers);
    assert.deepEqual([...got.keys()].sort(), Object.keys(c.keys).sort());
    for (const [k, v] of Object.entries(c.keys as Record<string, string>)) {
      assert.ok(sameNumber(decToString(got.get(k)!), v), `${k}: ${decToString(got.get(k)!)} != ${v}`);
    }
  }
});

test("verification reports", () => {
  for (const c of golden.verify) {
    const got = verifyText(c.fields, c.numbers, c.claims as Claim[] | null, c.chart_data ?? null);
    const want = c.report;
    for (const field of [
      "status", "checked", "unmatched", "years_out_of_range", "data_years", "allowed_values",
      "claims_checked", "uncovered", "format_issues",
    ]) {
      assert.deepEqual(got[field as keyof typeof got], want[field], `${c.name}.${field}`);
    } // prettier-ignore
    assert.equal(got.claims.length, want.claims.length, `${c.name}.claims`);
    got.claims.forEach((claim, i) => {
      const w = want.claims[i];
      const { key_values: kv, ...rest } = claim;
      const { key_values: wkv, ...wrest } = w;
      assert.deepEqual(rest, wrest, `${c.name}.claims[${i}]`);
      if (wkv || kv) {
        assert.deepEqual(Object.keys(kv ?? {}), Object.keys(wkv ?? {}));
        for (const k of Object.keys(wkv)) assert.ok(sameNumber(kv![k], wkv[k]), `${c.name} key_values ${k}`);
      }
    });
  }
});

test("narration reply validation", () => {
  for (const c of golden.narration) {
    let error: string | null = null;
    try {
      parseNarration(c.reply, c.chart_data);
    } catch (e) {
      assert.ok(e instanceof NarrationError, `${c.name}: unexpected ${e}`);
      error = (e as Error).message;
    }
    if (c.error === null) assert.equal(error, null, `${c.name}: ${error}`);
    else assert.ok(error?.includes(c.error), `${c.name}: expected "${c.error}" in "${error}"`);
  }
});

test("word counts and slugs", () => {
  for (const c of golden.word_count) assert.equal(wordCount(c.text), c.count, c.text);
  for (const c of golden.slugify) assert.equal(slugify(c.text), c.slug, c.text);
});

test("story shortlist", () => {
  const got = shortlist(golden.candidates.findings as FindingRow[]);
  const want = golden.candidates.shortlist;
  assert.equal(got.length, want.length);
  got.forEach((c, i) => {
    const w = want[i];
    assert.deepEqual(
      [c.geography, c.geo_level, c.good_news, c.finding_ids, c.measures, c.title],
      [w.geography, w.geo_level, w.good_news, w.finding_ids, w.measures, w.title],
    );
    assert.ok(Math.abs(c.score - w.score) < 1e-4);
  });
});

test("prompt (numbers compared by value: 7.0 and 7 are the same)", () => {
  const norm = (s: string) => s.replace(/-?\d+(?:\.\d+)?(?:e[+-]?\d+)?/gi, (m) => String(Number(m)));
  for (const c of golden.prompt) {
    assert.equal(norm(buildPrompt(c.numbers, c.chart_data, c.chart_spec)), norm(c.prompt));
    assert.equal(norm(narrationInstructions()), norm(c.instructions));
    assert.equal(STORY_REQUEST, c.request);
    assert.equal(norm(narrationData(c.numbers, c.chart_data, c.chart_spec)), norm(c.data));
  }
});

test("chart facts (rank and exclusivity checks)", () => {
  for (const c of golden.chartfacts.evaluate) {
    assert.deepEqual(evaluate(c.check, golden.chartfacts.chart_data), c.result, JSON.stringify(c.check));
  }
});

test("Python %g formatting", () => {
  const cases: [number, string][] = [
    [40, "40"], [27.5, "27.5"], [-0.5, "-0.5"], [5.4213, "5.4213"], [1234567, "1.23457e+06"],
    [0.00001, "1e-05"], [0.0001, "0.0001"], [123456, "123456"], [-2, "-2"], [0, "0"],
  ]; // prettier-ignore
  for (const [x, want] of cases) assert.equal(fmtG(x), want, String(x));
});

test("chart keys and chart text", () => {
  const got = Object.fromEntries([...chartKeys(golden.chartfacts.chart_data)].map(([k, v]) => [k, decToString(v)]));
  assert.deepEqual(Object.keys(got).sort(), Object.keys(golden.chart_keys).sort());
  for (const [k, v] of Object.entries(golden.chart_keys as Record<string, string>)) assert.ok(sameNumber(got[k], v), k);
  for (const c of golden.chart_text) assert.equal(chartText(c.spec), c.text);
});

test("API reply normalisation (\"\" and [] mean not used)", () => {
  for (const c of golden.normalise) assert.deepEqual(normaliseApiReply(c.reply), c.out);
});
